attributes.visState:
{"title": "[Tropobeat] CCI ops: verdicts by LRF, hour by hour", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": {
  "left": 20,
  "right": 20,
  "top": 18,
  "bottom": 12
 },
 "background": "#0F1F2C",
 "config": {
  "view": {
   "stroke": null
  },
  "legend": {
   "labelColor": "#8DA2B2",
   "labelFont": "ui-monospace,Menlo,Consolas,monospace",
   "labelFontSize": 11.5,
   "symbolType": "square",
   "symbolSize": 100,
   "symbolStrokeWidth": 0,
   "columnPadding": 14,
   "layout": {
    "top": {
     "anchor": "end"
    }
   }
  },
  "text": {
   "font": "\"Inter\",\"Segoe UI\",system-ui,sans-serif",
   "fill": "#E4EDF3"
  }
 },
 "title": {
  "text": "Verdicts by LRF, hour by hour",
  "subtitle": {
   "signal": "'WORST VERDICT IN THE HOUR · ' + 'LOCAL TIME (UTC' + timeFormat(now(), '%Z') + ')'"
  },
  "anchor": "start",
  "frame": "group",
  "offset": 12,
  "color": "#E4EDF3",
  "font": "\"Barlow Condensed\",\"Roboto Condensed\",\"Arial Narrow\",sans-serif",
  "fontSize": 22,
  "fontWeight": 600,
  "subtitleColor": "#8DA2B2",
  "subtitleFont": "ui-monospace,Menlo,Consolas,monospace",
  "subtitleFontSize": 11,
  "subtitlePadding": 4
 },
 "signals": [
  {
   "name": "labw",
   "value": 170
  },
  {
   "name": "ax",
   "value": 20
  },
  {
   "name": "rowh",
   "value": 34
  },
  {
   "name": "sevlabel",
   "value": [
    "CLEAR",
    "SINGLE SIDE",
    "UNPAIRED",
    "DUCTING UNKNOWN",
    "UNEXPLAINED",
    "CCI CONFIRMED"
   ]
  },
  {
   "name": "nrows",
   "update": "length(data('rows'))"
  }
 ],
 "data": [
  {
   "name": "lrfs",
   "format": {
    "property": "hits.hits"
   },
   "url": {
    "index": "lrf-coordinates",
    "body": {
     "size": 1000,
     "_source": [
      "code",
      "city",
      "state"
     ],
     "query": {
      "match_all": {}
     }
    }
   },
   "transform": [
    {
     "type": "formula",
     "as": "code",
     "expr": "datum._source.code"
    },
    {
     "type": "formula",
     "as": "place",
     "expr": "datum._source.city + ', ' + datum._source.state"
    }
   ]
  },
  {
   "name": "rowsRaw",
   "format": {
    "property": "aggregations.l.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "l": {
       "terms": {
        "field": "tropobeat.lrf_codes",
        "size": 14,
        "order": [
         {
          "m": "desc"
         },
         {
          "_count": "desc"
         }
        ]
       },
       "aggs": {
        "m": {
         "max": {
          "field": "tropobeat.correlation.severity"
         }
        },
        "h": {
         "date_histogram": {
          "field": "@timestamp",
          "fixed_interval": "1h",
          "min_doc_count": 0,
          "extended_bounds": {
           "min": {
            "%timefilter%": "min"
           },
           "max": {
            "%timefilter%": "max"
           }
          }
         },
         "aggs": {
          "s": {
           "max": {
            "field": "tropobeat.correlation.severity"
           }
          }
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "rows",
   "source": "rowsRaw",
   "transform": [
    {
     "type": "filter",
     "expr": "datum.m.value > 0"
    },
    {
     "type": "window",
     "ops": [
      "row_number"
     ],
     "as": [
      "r"
     ]
    },
    {
     "type": "lookup",
     "from": "lrfs",
     "key": "code",
     "fields": [
      "key"
     ],
     "values": [
      "place"
     ],
     "as": [
      "place"
     ],
     "default": ""
    }
   ]
  },
  {
   "name": "cells",
   "source": "rows",
   "transform": [
    {
     "type": "flatten",
     "fields": [
      "h.buckets"
     ],
     "as": [
      "hb"
     ]
    },
    {
     "type": "formula",
     "as": "t",
     "expr": "datum.hb.key"
    },
    {
     "type": "formula",
     "as": "sev",
     "expr": "datum.hb.s.value"
    }
   ]
  },
  {
   "name": "hoursRaw",
   "format": {
    "property": "aggregations.h.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "h": {
       "date_histogram": {
        "field": "@timestamp",
        "fixed_interval": "1h",
        "min_doc_count": 0,
        "extended_bounds": {
         "min": {
          "%timefilter%": "min"
         },
         "max": {
          "%timefilter%": "max"
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "hours",
   "source": "hoursRaw",
   "transform": [
    {
     "type": "project",
     "fields": [
      "key"
     ]
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "x",
   "type": "band",
   "domain": {
    "data": "hoursRaw",
    "field": "key",
    "sort": true
   },
   "range": [
    {
     "signal": "labw"
    },
    {
     "signal": "width"
    }
   ],
   "paddingInner": 0.08
  },
  {
   "name": "y",
   "type": "band",
   "domain": {
    "data": "rows",
    "field": "key",
    "sort": {
     "field": "r",
     "op": "min"
    }
   },
   "range": [
    0,
    {
     "signal": "min(height - ax, max(1, nrows) * rowh)"
    }
   ],
   "paddingInner": 0.1
  },
  {
   "name": "sev",
   "type": "ordinal",
   "domain": [
    0,
    1,
    2,
    3,
    4,
    5
   ],
   "range": [
    "#13283A",
    "#3E5C72",
    "#5D7C91",
    "#A88A4A",
    "#E0A458",
    "#FF6B5E"
   ]
  }
 ],
 "legends": [
  {
   "fill": "sev",
   "orient": "top",
   "direction": "horizontal",
   "offset": 6,
   "encode": {
    "labels": {
     "update": {
      "text": {
       "signal": "sevlabel[datum.value]"
      }
     }
    },
    "symbols": {
     "update": {
      "cornerRadius": {
       "value": 2
      }
     }
    }
   }
  }
 ],
 "marks": [
  {
   "type": "rect",
   "from": {
    "data": "cells"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "t"
     },
     "width": {
      "scale": "x",
      "band": 1
     },
     "y": {
      "scale": "y",
      "field": "key"
     },
     "height": {
      "scale": "y",
      "band": 1
     },
     "fill": {
      "signal": "scale('sev', datum.sev == null ? 0 : datum.sev)"
     },
     "cornerRadius": {
      "value": 2
     },
     "strokeWidth": {
      "value": 0
     },
     "tooltip": {
      "signal": "{title: datum.key + (datum.place ? ' · ' + datum.place : ''), 'Hour': timeFormat(datum.t, '%d %b %H:00'), 'Worst verdict': datum.sev == null ? 'no events' : sevlabel[datum.sev]}"
     }
    },
    "hover": {
     "stroke": {
      "value": "#E4EDF3"
     },
     "strokeWidth": {
      "value": 1
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "rows"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "scale": "y",
      "field": "key",
      "band": 0.5,
      "offset": {
       "signal": "bandwidth('y') >= 28 ? -1 : 0"
      }
     },
     "baseline": {
      "signal": "bandwidth('y') >= 28 ? 'bottom' : 'middle'"
     },
     "text": {
      "field": "key"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 13
     },
     "fontWeight": {
      "value": 500
     },
     "fill": {
      "value": "#E4EDF3"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "rows"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "scale": "y",
      "field": "key",
      "band": 0.5,
      "offset": 1
     },
     "baseline": {
      "value": "top"
     },
     "text": {
      "signal": "bandwidth('y') >= 28 ? datum.place : ''"
     },
     "limit": {
      "signal": "labw - 10"
     },
     "fontSize": {
      "value": 12
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "signal": "range('y')[1] + 5"
     },
     "baseline": {
      "value": "top"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "value": "LOCAL"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "hours"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "key",
      "band": 0.5
     },
     "y": {
      "signal": "range('y')[1] + 5"
     },
     "align": {
      "value": "center"
     },
     "baseline": {
      "value": "top"
     },
     "text": {
      "signal": "bandwidth('x') >= 18 || hours(datum.key) % 3 == 0 ? timeFormat(datum.key, '%H') : ''"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "width / 2"
     },
     "y": {
      "signal": "40"
     },
     "align": {
      "value": "center"
     },
     "fontSize": {
      "value": 13
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "signal": "nrows ? '' : 'No LRF had a verdict other than clear in this time range'"
     }
    }
   }
  }
 ]
}"}}
